-- ═══════════════ VERIFICACIÓN ═══════════════
select l.clave, count(*) as poligonos from public.cartografia_secciones c join public.licencias l on l.id=c.licencia_id group by 1 order by 1;
select l.clave, count(*) as secciones, count(distrito_federal) as con_df, count(total_votos) as con_votos, count(estatus_afluencia) as con_dificultad, count(lat) as con_centroide
from public.secciones_ine s join public.licencias l on l.id=s.licencia_id group by 1 order by 1;
